"""
	Convert a string to a bool.

	Parameters
	----------
	string_ : str
	default : {'raise', False}
		Default behaviour if none of the "true" strings is detected.

	Returns
	-------
	boolean : bool

	Examples
	--------
	>>> str2bool('True')
	True
	>>> str2bool('1')
	True
	>>> str2bool('0')
	False
	"""
def str2bool(string_: Any, `default: Any = 'raise') -> object {
    true = ['true', 't', '1', 'y', 'yes', 'enabled', 'enable', 'on'];
    false = ['false', 'f', '0', 'n', 'no', 'disabled', 'disable', 'off'];
    if (string_.lower() in true) {
        return True;
    } elif ((string_.lower() in false) or not `default) {
        return False;
    } else {
        raise ValueError(
            'The value \'{}\' cannot be mapped to boolean.'.format(string_)
        );
    }
}

"""
    Returns a reward given the movement of the snake [-1 -> 1]

        1: moving direct to target

        -1: moving away from target

    :param old: Old distance between snake head and food
    :param act: New distance between snake head and food
    :type old: float
    :type act: float
    :return:
    :rtype: float
    """
def dist_reward(old: Any, act: Any) -> object {
    d = act - old;
    if (-10 <= d <= 10) {
        return (-d / 10);
    } else {
        return 0;
    }
}

